INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2425226, 334890, 56828, '<td valign="top">Too much glare on the bottle slightly takes away from photo.</td>', 'Too much glare on the bottle slightly takes away from photo.', '2006-05-17 12:50:15.000000', NULL, 1),
(2425232, 335228, 16402, '<td valign="top">I love Guinness, so you get extra points just for the subject matter. I also like your overall concept. I do think the image is maybe just a bit too dark at the top. There''s not enought separation between the bottle and background.</td>', 'I love Guinness, so you get extra points just for the subject matter. I also like your overall concept. I do think the image is maybe just a bit too dark at the top. There''s not enought separation between the bottle and background.', '2006-05-17 12:50:59.000000', NULL, 1),
(2425233, 334089, 58682, '<td valign="top">although the lighting here is pretty good, the composition is not. your subject is almost in the middle here.. use the rule of thirds! You''ve started to use your DOF to create a Boke effect here but your backround is still a little cluttered. Nice use of color with the blue table cloth and the different colored fruit but your bananas are looking a little shabby. Look forward to seeing more from you!</td>', 'although the lighting here is pretty good, the composition is not. your subject is almost in the middle here.. use the rule of thirds! You''ve started to use your DOF to create a Boke effect here but your backround is still a little cluttered. Nice use of color with the blue table cloth and the different colored fruit but your bananas are looking a little shabby. Look forward to seeing more from you!', '2006-05-17 12:51:27.000000', NULL, 1),
(2425234, 334890, 48954, '<td valign="top">not in focus...crooked...the star effects are cool</td>', 'not in focus...crooked...the star effects are cool', '2006-05-17 12:52:27.000000', NULL, 1),
