(2426292, 333812, 53964, '<td valign="top">A still life generally brings together a number of elements arranged into an eyecatching grouping.  This may be someone''s life, but you haven''t arranged a still life, imo.</td>', 'A still life generally brings together a number of elements arranged into an eyecatching grouping.  This may be someone''s life, but you haven''t arranged a still life, imo.', '2006-05-17 16:05:03.000000', NULL, 1),
(2426300, 335258, 53964, '<td valign="top">Finally! :D</td>', 'Finally! :D', '2006-05-17 16:07:45.000000', NULL, 1),
(2426303, 335186, 53964, '<td valign="top">A still life generally brings together a number of elements arranged into a pleasing grouping. A closeup doesn''t allow for the element of the arrangement to come into play.</td>', 'A still life generally brings together a number of elements arranged into a pleasing grouping. A closeup doesn''t allow for the element of the arrangement to come into play.', '2006-05-17 16:08:22.000000', NULL, 1),
