(2434985, 333812, 47597, '<td valign="top">This is a snapshot and not a still life.</td>', 'This is a snapshot and not a still life.', '2006-05-19 10:40:56.000000', NULL, 1),
(2434999, 334424, 19507, '<td valign="top">Good color and the the flowers outside the frame add interest.</td>', 'Good color and the the flowers outside the frame add interest.', '2006-05-19 10:42:44.000000', NULL, 1),
(2435008, 335439, 19507, '<td valign="top">I think you could really improve on this shot with (1) some improvement in the lighting and (2) some adjustment to the levels in post processing to create some more contrast.</td>', 'I think you could really improve on this shot with (1) some improvement in the lighting and (2) some adjustment to the levels in post processing to create some more contrast.', '2006-05-19 10:44:28.000000', NULL, 1),
(2435009, 332787, 47597, '<td valign="top">I like the setup and theme. The line of light at the bottom doesn''t look nice to me, and I''d prefer to see stronger shadows in a still life.</td>', 'I like the setup and theme. The line of light at the bottom doesn''t look nice to me, and I''d prefer to see stronger shadows in a still life.', '2006-05-19 10:44:34.000000', NULL, 1),
(2435019, 335598, 47597, '<td valign="top">The light and dark areas are too strong. It''s hard to see the eggs in the bowls.</td>', 'The light and dark areas are too strong. It''s hard to see the eggs in the bowls.', '2006-05-19 10:45:39.000000', NULL, 1),
(2435028, 334653, 47597, '<td valign="top">Spectacular flower.</td>', 'Spectacular flower.', '2006-05-19 10:46:30.000000', NULL, 1),
(2435035, 333052, 47597, '<td valign="top">Beautiful DOF and lighting. I wish the pic was bigger.</td>', 'Beautiful DOF and lighting. I wish the pic was bigger.', '2006-05-19 10:47:19.000000', NULL, 1),
(2435045, 333702, 47597, '<td valign="top">Phew - that''s a hard way to live! I don''t think this is a still life though.</td>', 'Phew - that''s a hard way to live! I don''t think this is a still life though.', '2006-05-19 10:48:58.000000', NULL, 1),
(2435052, 334791, 47597, '<td valign="top">What an unusual subject - nice. Good DOF and lighting.</td>', 'What an unusual subject - nice. Good DOF and lighting.', '2006-05-19 10:50:22.000000', NULL, 1),
