(2447637, 332544, 39919, '<td valign="top">I would call this a landscape not a still life.  And either there are a lot of birds in the picture or your lense is dirty.</td>', 'I would call this a landscape not a still life.  And either there are a lot of birds in the picture or your lense is dirty.', '2006-05-22 20:42:22.000000', NULL, 1),
(2447640, 335499, 39919, '<td valign="top">Out of focus.</td>', 'Out of focus.', '2006-05-22 20:44:26.000000', NULL, 1),
(2447645, 335598, 39919, '<td valign="top">I am assuming that those are the separated egg yolks in the green bowl in the foreground, but they need to be better lit for me to be sure.</td>', 'I am assuming that those are the separated egg yolks in the green bowl in the foreground, but they need to be better lit for me to be sure.', '2006-05-22 20:46:40.000000', NULL, 1),
